import { createWorksFilterInterface, type WorksFilterState, type WorksSortMode } from './cms-works-filter';
import {
  isBackForwardNavigation,
  readWorksViewState,
  writeWorksViewState,
} from './modules/works-view-state';
import { initWorkOverlay } from './work-overlay';

interface WorkItem {
  id: string;
  title: string;
  thumbnail: string;
  thumbnailAlt: string;
  href: string;
  year: string;
  categories: string[];
  index: number;
}

interface ImageMeasure {
  width: number;
  height: number;
}

interface PlacedWorkColumn {
  items: WorkItem[];
  height: number;
}

const ROOT_SELECTOR = '[data-cms-works]';
const SOURCE_SELECTOR = '[data-cms-works-source]';
const ITEM_SELECTOR = '[data-cms-works-item], [data-cms-canvas-item]';
const THUMBNAIL_SELECTOR = '[data-works-thumbnail], [data-canvas-thumbnail]';
const TITLE_SELECTOR = '[data-works-title], [data-canvas-title]';
const YEAR_SELECTOR = '[data-works-year], [data-canvas-year]';
const CATEGORY_SELECTOR = '[data-works-category], [data-works-categories]';
const SVG_NAMESPACE = 'http://www.w3.org/2000/svg';
const LINK_SELECTOR = [
  '[data-works-link]',
  '[data-sheet-calendar-link]',
  '[data-sheet-calender-link]',
  '[data-sheet-claender-link]',
  '[data-calendar-link]',
  '[data-calender-link]',
  '[data-claender-link]',
  '[data-sheet-link]',
  'a[href]',
].join(', ');
const INITIAL_VISIBLE_COUNT = 16;
const LOAD_MORE_INCREMENT = 16;
const LOAD_MORE_TEMPLATE_SELECTOR = '[data-cms-works-load-more-template]';
const WORKS_READY_EVENT = 'site:works-ready';

function ready(callback: () => void): void {
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', callback, { once: true });
  } else {
    callback();
  }
}

function textFrom(element: HTMLElement, selector: string): string {
  return element.querySelector<HTMLElement>(selector)?.textContent?.trim() ?? '';
}

function directImageChildFrom(element: HTMLElement): HTMLImageElement | null {
  return Array.from(element.children).find((child): child is HTMLImageElement => child instanceof HTMLImageElement) ?? null;
}

function imageFrom(element: HTMLElement): HTMLImageElement | null {
  const target = element.querySelector<HTMLElement>(THUMBNAIL_SELECTOR);

  if (target) {
    return target instanceof HTMLImageElement ? target : null;
  }

  return directImageChildFrom(element);
}

function hashString(value: string): number {
  let hash = 2166136261;

  for (let index = 0; index < value.length; index += 1) {
    hash ^= value.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }

  return hash >>> 0;
}

function createRandom(seed: number): () => number {
  let state = seed >>> 0;

  return () => {
    state += 0x6d2b79f5;
    let value = state;
    value = Math.imul(value ^ (value >>> 15), value | 1);
    value ^= value + Math.imul(value ^ (value >>> 7), value | 61);
    return ((value ^ (value >>> 14)) >>> 0) / 4294967296;
  };
}

function readCategories(element: HTMLElement): string[] {
  const raw =
    element.getAttribute('data-works-categories') ??
    element.getAttribute('data-works-category') ??
    textFrom(element, CATEGORY_SELECTOR);

  return raw
    .split(',')
    .map((category) => category.trim())
    .filter(Boolean);
}

function readHref(element: HTMLElement): string {
  return (
    element.getAttribute('data-works-href') ??
    element.getAttribute('data-works-url') ??
    element.getAttribute('data-sheet-calendar-href') ??
    element.getAttribute('data-sheet-calendar-url') ??
    element.getAttribute('data-sheet-calender-href') ??
    element.getAttribute('data-sheet-calender-url') ??
    element.getAttribute('data-sheet-claender-href') ??
    element.getAttribute('data-sheet-claender-url') ??
    element.getAttribute('data-calendar-href') ??
    element.getAttribute('data-calendar-url') ??
    element.getAttribute('data-calender-href') ??
    element.getAttribute('data-calender-url') ??
    element.getAttribute('data-claender-href') ??
    element.getAttribute('data-claender-url') ??
    element.getAttribute('data-sheet-href') ??
    element.getAttribute('data-sheet-url') ??
    element.querySelector<HTMLAnchorElement>(LINK_SELECTOR)?.href ??
    ''
  );
}

function readItem(element: HTMLElement, index: number): WorkItem | null {
  const thumbnailElement = imageFrom(element);
  const thumbnail = thumbnailElement?.currentSrc || thumbnailElement?.src || '';

  if (!thumbnail) {
    return null;
  }

  const title =
    textFrom(element, TITLE_SELECTOR) ||
    element.getAttribute('data-works-title')?.trim() ||
    element.getAttribute('data-canvas-title')?.trim() ||
    thumbnailElement?.alt.trim() ||
    '';
  const href = readHref(element);
  let hrefSlug = '';
  try {
    hrefSlug = new URL(href, document.baseURI).pathname.split('/').filter(Boolean).pop() || '';
  } catch {
    // A sheet URL may not be a valid work detail URL.
  }
  const id =
    element.getAttribute('data-works-id')?.trim() ||
    element.getAttribute('data-canvas-id')?.trim() ||
    element.getAttribute('data-cms-item-id')?.trim() ||
    hrefSlug ||
    `work-${index + 1}-${hashString(`${title}-${thumbnail}`)}`;

  return {
    id,
    title,
    thumbnail,
    thumbnailAlt: thumbnailElement?.alt || title,
    href,
    year: textFrom(element, YEAR_SELECTOR) || element.getAttribute('data-works-year')?.trim() || '',
    categories: readCategories(element),
    index,
  };
}

function readItems(source: HTMLElement): WorkItem[] {
  return Array.from(source.querySelectorAll<HTMLElement>(ITEM_SELECTOR))
    .map(readItem)
    .filter((item): item is WorkItem => item !== null);
}

function releaseSourceImages(source: HTMLElement): void {
  for (const element of Array.from(source.querySelectorAll<HTMLElement>(ITEM_SELECTOR))) {
    const image = imageFrom(element);
    if (!image) continue;
    image.removeAttribute('srcset');
    image.removeAttribute('sizes');
    image.removeAttribute('src');
  }
}

function readSortMode(root: HTMLElement): WorksSortMode {
  const value = root.getAttribute('data-works-sort')?.trim().toLowerCase();

  if (value === 'random' || value === 'year') {
    return value;
  }

  return 'year';
}

function parseFirstYear(value: string): number | null {
  const match = value.match(/\b(?:18|19|20)\d{2}\b/);
  return match ? Number.parseInt(match[0], 10) : null;
}

function formatYear(value: string): string {
  const trimmedValue = value.trim();

  return trimmedValue.startsWith('[') && trimmedValue.endsWith(']') ? trimmedValue : `[${trimmedValue}]`;
}

function sortItems(items: WorkItem[], mode: WorksSortMode, root: HTMLElement): WorkItem[] {
  const nextItems = [...items];

  if (mode === 'random') {
    const seed = hashString(root.getAttribute('data-works-random-seed') || items.map((item) => item.id).join('|'));
    const random = createRandom(seed);

    return nextItems
      .map((item) => ({ item, sortValue: random() }))
      .sort((first, second) => first.sortValue - second.sortValue)
      .map(({ item }) => item);
  }

  return nextItems.sort((first, second) => {
    const firstYear = parseFirstYear(first.year) ?? Number.POSITIVE_INFINITY;
    const secondYear = parseFirstYear(second.year) ?? Number.POSITIVE_INFINITY;
    return firstYear - secondYear || first.title.localeCompare(second.title, 'de', { sensitivity: 'base' });
  });
}

function filterItems(items: WorkItem[], selectedCategories: Set<string>): WorkItem[] {
  if (selectedCategories.size === 0) {
    return items;
  }

  return items.filter((item) => item.categories.some((category) => selectedCategories.has(category)));
}

function createEyeIcon(): SVGSVGElement {
  const svg = document.createElementNS(SVG_NAMESPACE, 'svg');
  const pupil = document.createElementNS(SVG_NAMESPACE, 'path');
  const outline = document.createElementNS(SVG_NAMESPACE, 'path');

  svg.classList.add('cms-works__eye');
  svg.setAttribute('viewBox', '0 0 26 17');
  svg.setAttribute('fill', 'none');
  svg.setAttribute('aria-hidden', 'true');
  svg.setAttribute('focusable', 'false');

  pupil.classList.add('cms-works__eye-pupil');
  pupil.setAttribute('d', 'M12.9287 5.09348L9.21484 8.5L12.9287 11.9065L16.6426 8.5L12.9287 5.09348Z');
  pupil.setAttribute('fill', 'currentColor');

  outline.setAttribute(
    'd',
    'M13.0002 2.18023C15.6652 2.18023 18.1329 3.07008 20.3347 4.82508C21.9106 6.08117 22.9982 7.49402 23.6231 8.43757V8.56243C22.9982 9.50597 21.9106 10.9188 20.3347 12.1749C18.1329 13.9299 15.6652 14.8198 13.0002 14.8198C10.3349 14.8198 7.86705 13.9298 5.66511 12.1745C4.08924 10.9183 3.00176 9.50545 2.37694 8.56192V8.43809C3.00176 7.49455 4.08926 6.08168 5.66511 4.82548C7.86706 3.07023 10.3349 2.18023 13.0002 2.18023ZM13.0002 0C5.40921 0 1.20653 5.8629 0 7.85026V9.14973C1.20653 11.1371 5.40921 17 13.0002 17C20.5904 17 24.793 11.1382 26 9.1503V7.8497C24.793 5.8618 20.5904 0 13.0002 0Z',
  );
  outline.setAttribute('fill', 'currentColor');

  svg.append(pupil, outline);

  return svg;
}

function createWorkCard(item: WorkItem, measure: ImageMeasure, revealIndex = -1): HTMLElement {
  const card = document.createElement(item.href ? 'a' : 'article');
  const imageWrap = document.createElement('span');
  const image = document.createElement('img');
  const meta = document.createElement('span');
  const label = document.createElement('span');
  const title = document.createElement('span');

  card.className = 'cms-works__item';
  card.setAttribute('data-works-rendered-item', item.id);
  card.setAttribute('data-works-categories', item.categories.join(','));

  if (item.href) {
    card.classList.add('cms-works__item--clickable');
    card.setAttribute('href', item.href);
    card.setAttribute('data-work-overlay-trigger', item.id);
    card.setAttribute('data-transition', 'false');
  }

  imageWrap.className = 'cms-works__image-wrap';
  if (revealIndex >= 0) {
    imageWrap.classList.add('cms-works__image-wrap--revealing');
    imageWrap.style.setProperty('--cms-works-reveal-delay', `${revealIndex * 100}ms`);
  }

  image.className = 'cms-works__image';
  image.src = item.thumbnail;
  image.alt = item.thumbnailAlt;
  image.width = measure.width;
  image.height = measure.height;
  image.loading = 'lazy';
  image.decoding = 'async';
  imageWrap.append(image);

  meta.className = 'cms-works__meta';
  label.className = 'cms-works__label';

  title.className = 'cms-works__title';
  title.textContent = item.title;
  label.append(title);

  if (item.year) {
    const year = document.createElement('span');

    year.className = 'cms-works__year';
    year.textContent = formatYear(item.year);
    label.append(year);
  }

  meta.append(label, createEyeIcon());

  card.append(imageWrap, meta);

  return card;
}

function measureImage(src: string): Promise<ImageMeasure> {
  return new Promise((resolve) => {
    const image = new Image();

    image.onload = () => {
      resolve({
        width: image.naturalWidth || 1,
        height: image.naturalHeight || 1,
      });
    };
    image.onerror = () => resolve({ width: 1, height: 1 });
    image.src = src;
  });
}

function getColumnCount(root: HTMLElement): number {
  const styles = window.getComputedStyle(root);
  const rawValue = styles.getPropertyValue('--cms-works-active-columns').trim();
  const columnCount = Number.parseInt(rawValue, 10);

  return Number.isFinite(columnCount) && columnCount > 0 ? columnCount : 4;
}

function distributeItems(items: WorkItem[], measures: Map<string, ImageMeasure>, columnCount: number): PlacedWorkColumn[] {
  const columns: PlacedWorkColumn[] = Array.from({ length: columnCount }, () => ({
    items: [],
    height: 0,
  }));

  items.forEach((item) => {
    const measure = measures.get(item.id) ?? { width: 1, height: 1 };
    const column = columns.reduce((shortest, candidate) =>
      candidate.height < shortest.height ? candidate : shortest);

    column.items.push(item);
    column.height += measure.height / Math.max(measure.width, 1) + 0.18;
  });

  return columns;
}

function renderGrid(root: HTMLElement, items: WorkItem[], measures: Map<string, ImageMeasure>, revealedIds?: Set<string>): void {
  const grid = document.createElement('div');
  const columns = distributeItems(items, measures, getColumnCount(root));
  const revealOrder = new Map<string, number>();

  if (revealedIds) {
    items.forEach((item) => {
      if (revealedIds.has(item.id)) revealOrder.set(item.id, revealOrder.size);
    });
  }

  grid.className = 'cms-works__grid';

  columns.forEach((columnItems) => {
    const column = document.createElement('div');

    column.className = 'cms-works__column';
    columnItems.items.forEach((item) => {
      column.append(createWorkCard(item, measures.get(item.id) ?? { width: 1, height: 1 }, revealOrder.get(item.id) ?? -1));
    });
    grid.append(column);
  });

  root.replaceChildren(grid);
  root.classList.add('is-ready');
}

function setButtonText(button: HTMLElement, text: string): void {
  const textTarget =
    button.querySelector<HTMLElement>('[data-cms-works-load-more-text]') ??
    button.querySelector<HTMLElement>('[data-button-text]') ??
    button.querySelector<HTMLElement>('.button-text') ??
    button;

  textTarget.textContent = text;
}

function getLoadMoreButton(root: HTMLElement, source: HTMLElement): HTMLElement | null {
  const button =
    root.querySelector<HTMLElement>(LOAD_MORE_TEMPLATE_SELECTOR) ??
    source.querySelector<HTMLElement>(LOAD_MORE_TEMPLATE_SELECTOR) ??
    document.querySelector<HTMLElement>(LOAD_MORE_TEMPLATE_SELECTOR);

  if (!button) {
    return null;
  }

  if (button instanceof HTMLButtonElement) {
    button.type = 'button';
  }

  if (button instanceof HTMLAnchorElement) {
    button.href = '#';
  }

  button.setAttribute('role', 'button');
  button.setAttribute('tabindex', '0');
  button.removeAttribute('hidden');
  button.removeAttribute('aria-hidden');
  button.removeAttribute('data-cms-works-load-more-template');
  button.setAttribute('data-cms-works-load-more', '');
  setButtonText(button, 'MEHR ANZEIGEN');

  return button;
}

/**
 * Der Ansichtszustand wird nur wiederhergestellt, wenn der Nutzer wirklich von einer
 * Werkseite zurueckkommt. Ueber das Menue aufgerufen startet die Uebersicht frisch.
 */
function shouldRestoreView(): boolean {
  return isBackForwardNavigation();
}

function renderWorks(root: HTMLElement, source: HTMLElement): void {
  const items = readItems(source);
  const storedView = shouldRestoreView() ? readWorksViewState() : null;
  const restoredCategories = storedView?.categories ?? [];
  const state: WorksFilterState = {
    appliedCategories: new Set(restoredCategories),
    pendingCategories: new Set(restoredCategories),
    appliedSortMode: storedView?.sort ?? readSortMode(root),
    pendingSortMode: storedView?.sort ?? readSortMode(root),
    open: false,
  };
  const gridHost = document.createElement('div');
  const collectionOverlay = document.createElement('button');
  const gridMount = document.createElement('div');
  const loadMoreButton = getLoadMoreButton(root, source);
  let animationFrame = 0;
  let previousColumnCount = 0;
  let previousWidth = 0;
  let visibleCount = storedView?.visibleCount ?? INITIAL_VISIBLE_COUNT;
  let pendingScrollRestore = storedView?.scrollY ?? null;
  let currentItems: WorkItem[] = [];
  let measures = new Map<string, ImageMeasure>();
  const pendingMeasures = new Map<string, Promise<ImageMeasure>>();
  let renderRevision = 0;

  source.hidden = true;
  source.setAttribute('aria-hidden', 'true');
  releaseSourceImages(source);
  root.classList.add('cms-works');
  gridHost.className = 'cms-works__grid-host u-section';
  collectionOverlay.className = 'cms-works__collection-overlay';
  collectionOverlay.type = 'button';
  collectionOverlay.setAttribute('aria-label', 'Filter schliessen');
  gridMount.className = 'cms-works__grid-mount';
  gridHost.append(gridMount);

  if (loadMoreButton) {
    gridHost.append(loadMoreButton);
  }

  const getRenderedItems = () => sortItems(filterItems(items, state.appliedCategories), state.appliedSortMode, root);

  const renderCurrentItems = (force = false, revealedIds?: Set<string>) => {
    const revision = ++renderRevision;
    const visibleItems = currentItems.slice(0, visibleCount);

    void Promise.all(visibleItems.map(async (item) => {
      if (measures.has(item.id)) return;

      let pending = pendingMeasures.get(item.thumbnail);
      if (!pending) {
        pending = measureImage(item.thumbnail);
        pendingMeasures.set(item.thumbnail, pending);
      }

      measures.set(item.id, await pending);
    })).then(() => {
      if (revision !== renderRevision) return;

      window.cancelAnimationFrame(animationFrame);
      animationFrame = window.requestAnimationFrame(() => {
        if (revision !== renderRevision) return;

        const nextColumnCount = getColumnCount(root);
        const nextWidth = Math.round(root.getBoundingClientRect().width);

        if (!force && nextColumnCount === previousColumnCount && nextWidth === previousWidth) {
          return;
        }

        previousColumnCount = nextColumnCount;
        previousWidth = nextWidth;
        renderGrid(gridMount, visibleItems, measures, revealedIds);
        if (loadMoreButton) {
          loadMoreButton.hidden = currentItems.length <= visibleCount;
        }

        // Erst die alte Scrollposition, dann das Signal: der Flip misst die Kachel
        // sonst an der falschen Stelle.
        if (pendingScrollRestore !== null) {
          window.scrollTo(0, pendingScrollRestore);
          pendingScrollRestore = null;
        }

        root.setAttribute('data-site-assets-ready', '');
        document.dispatchEvent(
          new CustomEvent(WORKS_READY_EVENT, {
            bubbles: true,
            detail: { count: visibleItems.length, total: currentItems.length },
          }),
        );
      });
    });
  };
  const persistView = () => {
    writeWorksViewState({
      categories: Array.from(state.appliedCategories),
      sort: state.appliedSortMode,
      visibleCount,
      scrollY: window.scrollY,
      ts: Date.now(),
    });
  };
  const updateOverlayTop = () => {
    const panel = controls.element.querySelector<HTMLElement>('.cms-works-filter__panel');
    const bottom = panel?.getBoundingClientRect().bottom ?? controls.element.getBoundingClientRect().bottom;

    collectionOverlay.style.setProperty('--cms-works-overlay-top', `${Math.max(0, bottom)}px`);
  };
  const controls = createWorksFilterInterface(items, state, () => {
    currentItems = getRenderedItems();
    visibleCount = INITIAL_VISIBLE_COUNT;
    renderCurrentItems(true);
    controls.sync();
    persistView();
  }, {
    onOpenChange: (open) => {
      root.classList.toggle('is-filter-open', open);

      if (open) {
        updateOverlayTop();
      }
    },
  });
  collectionOverlay.addEventListener('click', () => controls.close(true));
  if (loadMoreButton) {
    const showMoreItems = () => {
      const previousCount = visibleCount;
      visibleCount = Math.min(visibleCount + LOAD_MORE_INCREMENT, currentItems.length);
      const revealedIds = new Set(currentItems.slice(previousCount, visibleCount).map((item) => item.id));
      renderCurrentItems(true, revealedIds);
      persistView();
    };
    loadMoreButton.addEventListener('click', (event) => {
      event.preventDefault();
      showMoreItems();
    });
    loadMoreButton.addEventListener('keydown', (event) => {
      if (event.key !== 'Enter' && event.key !== ' ') {
        return;
      }

      event.preventDefault();
      showMoreItems();
    });
  }

  currentItems = getRenderedItems();
  root.replaceChildren(controls.element, collectionOverlay, gridHost);
  initWorkOverlay(root, gridMount);

  const resizeObserver = new ResizeObserver(() => renderCurrentItems());

  renderCurrentItems(true);
  controls.sync();
  resizeObserver.observe(root);
  window.addEventListener('orientationchange', () => renderCurrentItems(true));
  window.addEventListener('resize', updateOverlayTop);
  window.addEventListener('scroll', updateOverlayTop, { passive: true });
  window.addEventListener('pagehide', persistView);
}

function mount(root: HTMLElement): void {
  const source = root.querySelector<HTMLElement>(SOURCE_SELECTOR) ?? document.querySelector<HTMLElement>(SOURCE_SELECTOR);

  if (!source) {
    console.error('CMS Works: Element mit data-cms-works-source wurde nicht gefunden.');
    return;
  }

  renderWorks(root, source);
}

ready(() => {
  const roots = Array.from(document.querySelectorAll<HTMLElement>(ROOT_SELECTOR));

  roots.forEach(mount);
});
